from collections import deque

def transform(g):
 h,w=len(g),len(g[0]); seen=set(); comps=[]
 for r in range(h):
  for c in range(w):
   v=g[r][c]
   if v==0 or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); comp=[]
   for x,y in q:
    comp.append((x,y,v))
    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=a<h and 0<=b<w and (a,b) not in seen and g[a][b]==v:
      seen.add((a,b)); q.append((a,b))
   comps.append(comp)
 out=[[0]*w for _ in range(h)]
 comps.sort(key=lambda x:max(c for r,c,v in x), reverse=True)
 for comp in comps:
  offset=0
  while True:
   nxt=[(r,c+offset+1,v) for r,c,v in comp]
   if any(c>=w or out[r][c] for r,c,v in nxt): break
   offset+=1
  for r,c,v in comp: out[r][c+offset]=v
 return out

